/**
 * @distilled.cloud/braintrust -- Braintrust API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-braintrust/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Braintrust from "@distilled.cloud/braintrust";
 *
 * const project = yield* Braintrust.createProject({ name: "my-project" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  BraintrustProtocol,
  type BraintrustOpError,
  type BraintrustOpContext,
} from "./protocol.ts";
export { paginateCursor, paginateKeyset } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts -- the ops raise the service-local
// classes.
export * from "./services/braintrust.ts";
export { BadRequest, Forbidden } from "./services/braintrust.ts";
